import { useState } from "react";
import { GraphRail } from "@/shared/ui/layouts/GraphRail";
import { RailSection } from "@/shared/ui/layouts/RailSection";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

type ProjectStatus = "active" | "shipped" | "in-progress" | "draft";
type AppType = "application" | "api" | "serverless" | "static" | "desktop" | "mobile" | "cli" | "library";

interface StatusFacet { value: ProjectStatus; label: string; dot: string }
const STATUS_FACETS: StatusFacet[] = [
  { value: "active",      label: "active",      dot: "var(--success)" },
  { value: "shipped",     label: "shipped",     dot: "var(--fg-dim)" },
  { value: "in-progress", label: "in progress", dot: "var(--violet)" },
  { value: "draft",       label: "draft",       dot: "var(--accent)" },
];
interface TypeFacet { value: AppType; label: string; color: string }
const TYPE_FACETS: TypeFacet[] = [
  { value: "application", label: "application", color: "var(--accent)" },
  { value: "api",         label: "api",         color: "var(--success)" },
  { value: "serverless",  label: "serverless",  color: "var(--danger)" },
  { value: "static",      label: "static site", color: "color-mix(in oklch, var(--info), var(--success))" },
  { value: "desktop",     label: "desktop app", color: "var(--violet)" },
  { value: "mobile",      label: "mobile app",  color: "var(--info)" },
  { value: "cli",         label: "cli",         color: "color-mix(in oklch, var(--accent), var(--violet))" },
  { value: "library",     label: "library",     color: "var(--fg-dim)" },
];

interface RailSections {
  isOpen: (key: string) => boolean;
  toggle: (key: string) => void;
}
function useRailSections(defaultOpen = true): RailSections {
  const [open, setOpen] = useState<Record<string, boolean>>({});
  return {
    isOpen: (key) => open[key] ?? defaultOpen,
    toggle: (key) => setOpen((o) => ({ ...o, [key]: !(o[key] ?? defaultOpen) })),
  };
}

export interface ProjectsRailProps {
  query: string;
  statusSel: Set<ProjectStatus>;
  toggleStatus: (s: ProjectStatus) => void;
  typeSel: Set<AppType>;
  toggleType: (t: AppType) => void;
  counts: Record<ProjectStatus, number>;
  typeCountsByCat: Record<AppType, number>;
  total: number;
  onClearStatus: () => void;
  onClearType: () => void;
  onClearFilters: () => void;
}
export function ProjectsRail({
  query = "", statusSel = new Set(), toggleStatus = () => {}, typeSel = new Set(), toggleType = () => {},
  counts = { active: 4, shipped: 2, "in-progress": 1, draft: 3 },
  typeCountsByCat = { application: 5, api: 2, serverless: 0, static: 1, desktop: 0, mobile: 1, cli: 0, library: 1 },
  total = 10, onClearStatus = () => {}, onClearType = () => {}, onClearFilters = () => {},
}: ProjectsRailProps) {
  const railSections = useRailSections();
  const anyFilter = statusSel.size > 0 || typeSel.size > 0 || query.trim().length > 0;

  return (
    <GraphRail
      bodyPad="12px 10px 20px"
      footer={anyFilter ? (
        <Box style={{ borderTop: "1px solid var(--border-soft)", padding: "10px 12px" }}>
          <Box as="button" onClick={onClearFilters} style={{ fontSize: 11, color: "var(--fg-muted)", background: "none", border: "none", cursor: "pointer", textDecoration: "underline", padding: 0 }}>
            clear all filters
          </Box>
        </Box>
      ) : undefined}
    >
      <RailSection
        label="Status"
        count={STATUS_FACETS.length}
        open={railSections.isOpen("status")}
        onToggle={() => railSections.toggle("status")}
      >
        <RailRow
          active={statusSel.size === 0}
          onClick={onClearStatus}
          leading={<Box as="span" style={{ width: 13, textAlign: "center", color: statusSel.size === 0 ? "var(--accent)" : "var(--fg-dim)" }}>≡</Box>}
          trailing={<Text as="span" mono size={10} tone="dim">{total}</Text>}
        >
          All
        </RailRow>
        {STATUS_FACETS.map((f) => {
          const on = statusSel.has(f.value);
          return (
            <RailRow
              key={f.value}
              data-status={f.value}
              active={on}
              aria-pressed={on}
              onClick={() => toggleStatus(f.value)}
              leading={<>
                <Toggle on={on} size="xs" />
                <Box as="span" bg={f.dot} radius={99} style={{ width: 8, height: 8, flex: "0 0 8px", marginLeft: 6 }} />
              </>}
              trailing={<Text as="span" mono size={10} tone="dim">{counts[f.value]}</Text>}
            >
              <Box as="span" style={{ textTransform: "capitalize" }}>{f.label}</Box>
            </RailRow>
          );
        })}
      </RailSection>

      <RailSection
        label="Type"
        count={TYPE_FACETS.length}
        open={railSections.isOpen("type")}
        onToggle={() => railSections.toggle("type")}
      >
        <RailRow
          active={typeSel.size === 0}
          onClick={onClearType}
          leading={<Box as="span" style={{ width: 13, textAlign: "center", color: typeSel.size === 0 ? "var(--accent)" : "var(--fg-dim)" }}>≡</Box>}
          trailing={<Text as="span" mono size={10} tone="dim">{total}</Text>}
        >
          All
        </RailRow>
        {TYPE_FACETS.map((f) => {
          const on = typeSel.has(f.value);
          return (
            <RailRow
              key={f.value}
              data-type={f.value}
              active={on}
              aria-pressed={on}
              onClick={() => toggleType(f.value)}
              leading={<>
                <Toggle on={on} size="xs" />
                <Box as="span" bg={f.color} radius={99} style={{ width: 8, height: 8, flex: "0 0 8px", marginLeft: 6 }} />
              </>}
              trailing={<Text as="span" mono size={10} tone="dim">{typeCountsByCat[f.value]}</Text>}
            >
              <Box as="span" style={{ textTransform: "capitalize" }}>{f.label}</Box>
            </RailRow>
          );
        })}
      </RailSection>
    </GraphRail>
  );
}
